function out = analyze_bds23_isb_dd(varargin)
% analyze_bds23_isb_dd  BDS-2/BDS-3 ISB analysis by SD+DD pseudorange method
%
% Method (aligned with literature idea):
%   1) Inter-system single difference (SD) per receiver:
%      SD_r(t) = median(P_r^BDS2(t)) - median(P_r^BDS3(t))
%   2) Inter-station double difference (DD):
%      ISB_DD(t) = SD_i(t) - SD_j(t)
%
% Here P uses bias-corrected code pseudorange (C1 - C1_bias), extracted from
% data4plot.mat generated by raPPPid. This avoids using filter state param(20)
% directly and is closer to observation-domain ISB analysis in papers.
%
% USAGE:
%   out = analyze_bds23_isb_dd()                         % interactive pick 2 result dirs
%   out = analyze_bds23_isb_dd(dir_i, dir_j)
%   out = analyze_bds23_isb_dd(dir_i, dir_j, 'skipEpochs', 0)
%
% OPTIONAL NAME-VALUE:
%   'skipEpochs'   : number of initial matched epochs skipped (default 0)
%   'outputRoot'   : root output folder (default RESULTS/ISB_DD_ANALYSIS)
%   'minSatsEach'  : min #sats for BDS2 and BDS3 at each station (default 1)
%   'consistencyTol': tolerance [m] for i-j vs -(j-i) check (default 1e-6)
%
% OUTPUT:
%   out struct with fields:
%     .summary, .tables, .outputDir
%
% This function belongs to raPPPid, Copyright (c) 2023, M.F. Glaner
% *************************************************************************

opts.skipEpochs = 0;
opts.outputRoot = fullfile('RESULTS', 'ISB_DD_ANALYSIS');
opts.minSatsEach = 1;
opts.outlierK = 3;
opts.consistencyTol = 1e-6;

[dir_i, dir_j, opts] = parseInputs(opts, varargin{:});

S_i = loadData4plot(dir_i);
S_j = loadData4plot(dir_j);

[P_i, t_i] = getBiasCorrectedCode(S_i.storeData);
[P_j, t_j] = getBiasCorrectedCode(S_j.storeData);

[sow_common, idx_i, idx_j] = intersect(t_i, t_j, 'stable');
if isempty(sow_common)
    error('No common epochs between the two result folders.');
end

% skip initial matched epochs (convergence/warm-up)
if numel(sow_common) <= opts.skipEpochs
    error('Common epochs (%d) <= skipEpochs (%d).', numel(sow_common), opts.skipEpochs);
end
keep = (opts.skipEpochs+1):numel(sow_common);
sow = sow_common(keep);
Pi = P_i(idx_i(keep), :);
Pj = P_j(idx_j(keep), :);

satCols = 1:size(Pi,2);
[isBDS2, isBDS3] = splitBDS2BDS3Cols(satCols);

n = numel(sow);
SD_i = NaN(n,1);
SD_j = NaN(n,1);
ISB_DD = NaN(n,1);
nb2_i = zeros(n,1); nb3_i = zeros(n,1);
nb2_j = zeros(n,1); nb3_j = zeros(n,1);

for k = 1:n
    pi = Pi(k,:);
    pj = Pj(k,:);

    b2_i = pi(isBDS2); b3_i = pi(isBDS3);
    b2_j = pj(isBDS2); b3_j = pj(isBDS3);

    b2_i = b2_i(isfinite(b2_i)); b3_i = b3_i(isfinite(b3_i));
    b2_j = b2_j(isfinite(b2_j)); b3_j = b3_j(isfinite(b3_j));

    nb2_i(k) = numel(b2_i); nb3_i(k) = numel(b3_i);
    nb2_j(k) = numel(b2_j); nb3_j(k) = numel(b3_j);

    if numel(b2_i) >= opts.minSatsEach && numel(b3_i) >= opts.minSatsEach
        SD_i(k) = median(b2_i) - median(b3_i);
    end
    if numel(b2_j) >= opts.minSatsEach && numel(b3_j) >= opts.minSatsEach
        SD_j(k) = median(b2_j) - median(b3_j);
    end

    if isfinite(SD_i(k)) && isfinite(SD_j(k))
        ISB_DD(k) = SD_i(k) - SD_j(k);
    end
end

valid = isfinite(ISB_DD);
if ~any(valid)
    error('No valid ISB_DD epochs after filtering.');
end

% bidirectional consistency check: (i-j) + (j-i) should be ~0
ISB_DD_rev = SD_j - SD_i;
consMask = valid & isfinite(ISB_DD_rev);
if any(consMask)
    consErr = ISB_DD(consMask) + ISB_DD_rev(consMask);
    summary.consistency_err_mean_m = mean(consErr, 'omitnan');
    summary.consistency_err_median_m = median(consErr, 'omitnan');
    summary.consistency_err_maxabs_m = max(abs(consErr), [], 'omitnan');
    summary.consistency_n = sum(consMask);
    summary.consistency_tol_m = opts.consistencyTol;
    summary.consistency_pass = summary.consistency_err_maxabs_m <= opts.consistencyTol;
else
    summary.consistency_err_mean_m = NaN;
    summary.consistency_err_median_m = NaN;
    summary.consistency_err_maxabs_m = NaN;
    summary.consistency_n = 0;
    summary.consistency_tol_m = opts.consistencyTol;
    summary.consistency_pass = false;
end

isb = ISB_DD(valid);
summary.mean_m = mean(isb, 'omitnan');
summary.median_m = median(isb, 'omitnan');
summary.std_m = std(isb, 'omitnan');
summary.mad_m = median(abs(isb - summary.median_m), 'omitnan');
summary.p10_m = localPrctile(isb, 10);
summary.p90_m = localPrctile(isb, 90);
summary.n_valid = sum(valid);
summary.n_total = n;

robustSigma = 1.4826 * summary.mad_m;
if isfinite(robustSigma) && robustSigma > 0
    outlierThr = opts.outlierK * robustSigma;
    inlierValid = abs(isb - summary.median_m) <= outlierThr;
else
    outlierThr = NaN;
    inlierValid = true(size(isb));
end

summary.outlier_k = opts.outlierK;
summary.outlier_thr_m = outlierThr;
summary.n_inlier = sum(inlierValid);
summary.n_outlier = numel(inlierValid) - summary.n_inlier;

if any(inlierValid)
    isb_inlier = isb(inlierValid);
    summary.mean_inlier_m = mean(isb_inlier, 'omitnan');
    summary.std_inlier_m = std(isb_inlier, 'omitnan');
else
    summary.mean_inlier_m = NaN;
    summary.std_inlier_m = NaN;
end

isOutlierEpoch = false(n,1);
validIdx = find(valid);
isOutlierEpoch(validIdx(~inlierValid)) = true;

% hourly means for figure similar to paper
hourTag = floor((sow - sow(1))/3600);
uh = unique(hourTag(valid));
hour_mean = NaN(numel(uh),1);
for i = 1:numel(uh)
    x = ISB_DD(hourTag==uh(i) & valid);
    hour_mean(i) = mean(x, 'omitnan');
end

stamp = datestr(now, 'yyyymmdd_HHMMSS');
outDir = fullfile(opts.outputRoot, ['DD_' stamp]);
if ~exist(outDir, 'dir'), mkdir(outDir); end

T_epoch = table(sow, SD_i, SD_j, ISB_DD, nb2_i, nb3_i, nb2_j, nb3_j, ...
    isOutlierEpoch, 'VariableNames', {'gpstime_sow','SD_i_m','SD_j_m','ISB_DD_m','nBDS2_i','nBDS3_i','nBDS2_j','nBDS3_j','is_outlier'});
T_hour = table(uh, hour_mean, 'VariableNames', {'hour_index','ISB_DD_mean_m'});
T_sum = struct2table(summary);

writetable(T_epoch, fullfile(outDir, 'isb_dd_epoch.csv'));
writetable(T_hour, fullfile(outDir, 'isb_dd_hourly_mean.csv'));
writetable(T_sum, fullfile(outDir, 'isb_dd_summary.csv'));

fid = fopen(fullfile(outDir, 'summary.txt'), 'w');
fprintf(fid, 'BDS2/BDS3 ISB DD analysis\n');
fprintf(fid, 'Dir i: %s\n', dir_i);
fprintf(fid, 'Dir j: %s\n', dir_j);
fprintf(fid, 'skipEpochs: %d\n', opts.skipEpochs);
fprintf(fid, 'valid/total: %d/%d\n', summary.n_valid, summary.n_total);
fprintf(fid, 'mean   [m]: %+0.4f\n', summary.mean_m);
fprintf(fid, 'median [m]: %+0.4f\n', summary.median_m);
fprintf(fid, 'std    [m]: %0.4f\n', summary.std_m);
fprintf(fid, 'mad    [m]: %0.4f\n', summary.mad_m);
fprintf(fid, 'p10/p90[m]: [%+0.4f, %+0.4f]\n', summary.p10_m, summary.p90_m);
fprintf(fid, 'outlier k    : %0.2f\n', summary.outlier_k);
fprintf(fid, 'outlier thr[m]: %0.4f\n', summary.outlier_thr_m);
fprintf(fid, 'inlier/outlier: %d / %d\n', summary.n_inlier, summary.n_outlier);
fprintf(fid, 'mean(inlier)[m]: %+0.4f\n', summary.mean_inlier_m);
fprintf(fid, 'std(inlier) [m]: %0.4f\n', summary.std_inlier_m);
fprintf(fid, 'consistency n: %d\n', summary.consistency_n);
fprintf(fid, 'cons err mean/med/maxabs [m]: %+0.6g / %+0.6g / %0.6g\n', ...
    summary.consistency_err_mean_m, summary.consistency_err_median_m, summary.consistency_err_maxabs_m);
fprintf(fid, 'cons tol [m]: %0.6g\n', summary.consistency_tol_m);
fprintf(fid, 'cons pass   : %d\n', summary.consistency_pass);
fclose(fid);

fig = figure('Name','BDS2/BDS3 ISB DD','NumberTitle','off');
subplot(2,1,1);
plot(sow(valid), ISB_DD(valid), '.', 'MarkerSize', 4); hold on;
yline(summary.mean_m, 'r-', 'LineWidth', 1.5);
yline(summary.median_m, 'k--', 'LineWidth', 1.2);
xlabel('GPS time [sow]'); ylabel('ISB DD [m]'); grid on;
legend({'ISB DD','mean','median'}, 'Location', 'best');

t1 = subplot(2,1,2);
plot(uh, hour_mean, '-o', 'LineWidth', 1.2, 'MarkerSize', 5);
xlabel('Hour index from start'); ylabel('Hourly mean ISB DD [m]'); grid on;
linkaxes([subplot(2,1,1), t1], 'x'); %#ok<LAXES>

saveas(fig, fullfile(outDir, 'isb_dd_plots.png'));

fprintf('\n=== BDS2/BDS3 ISB DD analysis ===\n');
fprintf('mean   : %+0.4f m\n', summary.mean_m);
fprintf('median : %+0.4f m\n', summary.median_m);
fprintf('std    : %0.4f m\n', summary.std_m);
fprintf('inlier : %d (outlier %d), k=%0.2f\n', summary.n_inlier, summary.n_outlier, summary.outlier_k);
fprintf('mean(inlier): %+0.4f m\n', summary.mean_inlier_m);
fprintf('std(inlier) : %0.4f m\n', summary.std_inlier_m);
fprintf('consistency : pass=%d, max|e|=%0.6g m (tol=%0.6g, n=%d)\n', ...
    summary.consistency_pass, summary.consistency_err_maxabs_m, summary.consistency_tol_m, summary.consistency_n);
fprintf('valid  : %d / %d epochs\n', summary.n_valid, summary.n_total);
fprintf('output : %s\n\n', outDir);

out = struct();
out.summary = summary;
out.tables.epoch = T_epoch;
out.tables.hourly = T_hour;
out.tables.summary = T_sum;
out.outputDir = outDir;

end


function [dir_i, dir_j, opts] = parseInputs(opts, varargin)
if nargin >= 3 && ischar(varargin{1}) && ischar(varargin{2})
    dir_i = varargin{1};
    dir_j = varargin{2};
    rest = varargin(3:end);
else
    dir_i = pickResultDir('Select receiver i result folder');
    dir_j = pickResultDir('Select receiver j result folder');
    rest = varargin;
end

if mod(numel(rest),2) ~= 0
    error('Name-value options must be paired.');
end
for k = 1:2:numel(rest)
    key = lower(string(rest{k}));
    val = rest{k+1};
    switch key
        case "skipepochs"
            opts.skipEpochs = max(0, round(val));
        case "outputroot"
            opts.outputRoot = char(val);
        case "minsatseach"
            opts.minSatsEach = max(1, round(val));
        case "outlierk"
            opts.outlierK = max(0, double(val));
        case "consistencytol"
            opts.consistencyTol = max(0, double(val));
        otherwise
            error('Unknown option: %s', rest{k});
    end
end
end


function d = pickResultDir(msg)
d = uigetdir(pwd, msg);
if isequal(d,0)
    error('User canceled folder selection.');
end
end


function S = loadData4plot(resultDir)
f = fullfile(resultDir, 'data4plot.mat');
if ~exist(f, 'file')
    error('Missing data4plot.mat in %s', resultDir);
end
S = load(f, 'storeData');
if ~isfield(S, 'storeData')
    error('storeData not found in %s', f);
end
end


function [P, sow] = getBiasCorrectedCode(storeData)
if ~isfield(storeData, 'C1') || ~isfield(storeData, 'gpstime')
    error('storeData missing C1 or gpstime.');
end
P = full(storeData.C1);
if isfield(storeData, 'C1_bias')
    P = P - full(storeData.C1_bias);
end
P(P==0) = NaN;
sow = storeData.gpstime(:);
end


function [isBDS2, isBDS3] = splitBDS2BDS3Cols(cols)
isBDS = cols >= 300 & cols < 400;
sv = mod(cols, 100);
isBDS2 = isBDS & sv >= 1 & sv <= 18;
isBDS3 = isBDS & sv >= 19 & sv <= 62;
end


function p = localPrctile(x, q)
x = x(isfinite(x));
if isempty(x)
    p = NaN; return;
end
x = sort(x(:));
n = numel(x);
if n == 1
    p = x; return;
end
k = (q/100) * (n-1) + 1;
k0 = floor(k);
k1 = ceil(k);
if k0 == k1
    p = x(k0);
else
    a = k - k0;
    p = (1-a)*x(k0) + a*x(k1);
end
end
